INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.47, "クローチェ", -470, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 2, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 1, 0, 126401, 10001, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.15, "クローチェ", -470, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 0, 126401, 10002, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ライラエル", -470, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 2, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 1, 0, 126501, 10003, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ライラエル", -470, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 0, 126501, 10004, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "リンド", -470, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 0, 127702, 10005, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "リンド", -470, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 0, 127702, 10006, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴルム", -470, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 2, 0, 127802, 10007, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.5, "ヴルム", -470, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 1, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, 0, 127802, 10008, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "アネモネ", -470, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 3, 0, 129602, 10009, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "アネモネ", -470, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 1, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 3, 0, 129602, 10010, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ネフィ=ネラ", -470, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 3, 0, 129701, 10011, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.2, "ネフィ=ネラ", -470, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 1, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 3, 0, 129701, 10012, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.1, "カノン", -470, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 5, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 4, 0, 130301, 10013, 3, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.15, "カノン", -470, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 4, 0, 130301, 10014, 3, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ナーナ", -470, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 4, 0, 130401, 10015, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.35, "ナーナ", -470, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 1, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 4, 0, 130401, 10016, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ホウオウ", -470, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 5, 0, 130502, 10017, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.18, "ホウオウ", -470, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 1, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 5, 0, 130502, 10018, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ホウオウ", -470, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 5, 0, 130503, 10019, 4, 3, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.9, "ネア", -470, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 2, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 5, 0, 123301, 10020, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.8, "ネア", -470, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 5, 0, 123301, 10021, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.922, "カリザ", -470, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 6, 0, 133301, 10022, 3, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (9.638, "カリザ", -470, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 5, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 6, 0, 133301, 10023, 3, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.88, "ミーア", -470, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 2, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 6, 0, 133401, 10024, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.818, "ミーア", -470, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 1, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 6, 0, 133401, 10025, 5, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.78, "グレイス", -470, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 7, 0, 133002, 10026, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.15, "グレイス", -470, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 0, 133002, 10027, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.28, "ヴァイオレット", -470, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 2, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 7, 0, 133102, 10028, 6, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴァイオレット", -470, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 7, 0, 133102, 10029, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.53, "ルルィ", -470, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 8, 0, 136902, 10030, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.05, "ルルィ", -470, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 7, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 8, 0, 136902, 10031, 9, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "デュラン", -470, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 8, 0, 137001, 10032, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "デュラン", -470, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 1, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 8, 0, 137001, 10033, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "サツキ", -470, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 2, "おう\n好きなもん持ってきな", 9, 0, 135902, 10034, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.935, "サツキ", -470, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 6, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 9, 0, 135902, 10035, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.441, "ユキノ", -470, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 5, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 9, 0, 135802, 10036, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ユキノ", -470, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 9, 0, 135802, 10037, 7, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.295, "クルル", -470, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 10, 0, 130901, 10038, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.281, "クルル", -470, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 6, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 10, 0, 130901, 10039, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.549, "ヴォルガーノ", -470, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 10, 0, 137701, 10040, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.64, "ヴォルガーノ", -470, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 6, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 10, 0, 137701, 10041, 3, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.642, "ライラエル", -470, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 4, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 11, 0, 132801, 10042, 7, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ライラエル", -470, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 11, 0, 132802, 10043, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "クローチェ", -470, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 11, 0, 134502, 10044, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.72, "クローチェ", -470, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 1, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 11, 0, 134501, 10045, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.991, "ネフィ＝ネラ", -470, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 12, 0, 138201, 10046, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.877, "ネフィ＝ネラ", -470, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 4, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 12, 0, 138201, 10047, 1, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.71, "アラクネ", -470, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 6, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 12, 0, 136001, 10048, 4, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.32, "アラクネ", -470, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 12, 0, 136001, 10049, 5, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.727, "アネモネ", -470, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 4, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 13, 0, 135401, 10050, 9, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.213, "アネモネ", -470, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 9, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 13, 0, 135401, 10051, 7, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.874, "クリア", -470, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 2, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 13, 0, 135301, 10052, 1, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "クリア", -470, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 2, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 13, 0, 135301, 10053, 2, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.215, "ヴァイオレット", -470, "2026/09/15 12:00:00", "2026/12/22 11:59:59", 1, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 14, 0, 138001, 10054, 2, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴァイオレット", -470, "2026/09/15 12:00:00", "2026/12/22 11:59:59", 4, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 14, 0, 138001, 10055, 4, 2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.477, "グレイス", -470, "2026/09/15 12:00:00", "2026/12/22 11:59:59", 1, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", 14, 0, 138901, 10056, 6, 1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.743, "グレイス", -470, "2026/09/15 12:00:00", "2026/12/22 11:59:59", 1, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", 14, 0, 138901, 10057, 2, 2, 2002);
